import React, { useState, useEffect } from "react";
import About1 from "./About1.jpg";
import About2 from "./About2.jpg";
import Purple from "./Purple.png";
import Footer from "./Footer";

function Invitational() {
  	return (
		<div className="home">
			<div 
				style={{
					maxWidth: "100vw",
					minHeight: "100vh",
					position: "relative",
					overflow: "hidden"
				}}
				>
				<div 
				style={{ 
					maxWidth: '1280px',
					display: 'flex',
					flexDirection: 'column',
					justifyContent: 'center',
					alignItems: 'center', 
					margin: '0 auto',
					paddingLeft: Math.max(40, (100 - (1280 / window.innerWidth) * 100) / 2) + 'px', 
					paddingRight: Math.max(40, (100 - (1280 / window.innerWidth) * 100) / 2) + 'px',
				}}
				>
				<div className="first-section">
					<div className="section-title">
					<div style={{ zIndex: 1 }}>
						<h1>
						2026 Invitational
						</h1>
						<hr class="solid"/>
						<p>
						Our fifth annual Northwestern Invitational will take place in-person at our Evanston campus on February 21st, 2026. 
						</p>
					</div>
					</div>
				</div>
				<div className="first-section">
					<div
					style={{
						minHeight: "25vh",
						maxWidth: "100%",
						display: "flex",
						textAlign: "start",
						flexDirection: "column"
					}}
								>
					<div style={{ zIndex: 1 }}>
						<h1>
						Registration
						</h1>
						<hr class="solid"/>
						<p
						style={{
							marginTop: "50px"
						}}
						>
						Registration for this tournament has closed.
						</p>
						<div
						style={{
							display: "flex",
							flexDirection: "row",
							marginTop: "50px"
						}}
					>
						<a href={'https://scilympiad.com/il-nu'}>
							<div className="button" style={{ marginRight: "50px", marginBottom: "25px" }}>
								SCILYMPIAD
							</div>
						</a>
					</div>
					</div>
					</div>
				</div>
				</div>
			</div>
		</div> 
	);
}

export default Invitational;
